function play(dd){if(!dd)return;clearTimeout(dd._t);dd.classList.remove('play','still');void dd.offsetWidth;
 const st=calm();dd.classList.add('play');if(st)dd.classList.add('still');
 dd._t=setTimeout(()=>dd.classList.remove('play','still'),st?4200:(+dd.dataset.ms||3000)+400)}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('.dd-btn');if(!b)return;e.preventDefault();play(b.parentElement.querySelector('.dd'))});

